-- 0029_dictionary_seed: Kernel 7 priority seed (Parity Build Order Phase 1).
-- Source: vendored Dolibarr install data at
--   .forgeerp-temp/dolibarr/htdocs/install/mysql/data/llx_*.sql
-- (llx_00_c_country, llx_10_c_regions, llx_c_currencies, llx_c_payment_term,
-- llx_c_paiement, llx_c_tva, llx_c_units, llx_c_civilite, llx_c_incoterms,
-- llx_c_shipment_mode, llx_c_transport_mode).
--
-- Idempotent: every INSERT uses ON CONFLICT DO NOTHING, so re-applying
-- changes no row counts. All seed rows are core (extra->>'core' = 'true';
-- is_core = TRUE): the dict store deactivates — never hard-deletes — them.
-- Money/rate precision: VAT rates are stored as integer basis points in
-- extra.rate_bps (percent * 100, e.g. 20% -> 2000); non-numeric legacy
-- taux values keep extra.rate_bps absent and the verbatim text in
-- extra.rate_text. No floats anywhere.

INSERT INTO ferp_dictionaries (code, label, scope)
SELECT * FROM (VALUES
    ('country', 'Countries (ISO 3166)', 'global'),
    ('region', 'Regions / states', 'global'),
    ('currency', 'Currencies (ISO 4217)', 'global'),
    ('payment_term', 'Payment terms', 'global'),
    ('payment_method', 'Payment methods', 'global'),
    ('vat_rate', 'VAT rates', 'global'),
    ('unit', 'Units of measure', 'global'),
    ('civility', 'Civilities', 'global'),
    ('incoterm', 'Incoterms 2025', 'global'),
    ('shipping_mode', 'Shipping modes', 'global'),
    ('transport_mode', 'Transport modes', 'global')
) AS v (code, label, scope)
ON CONFLICT (code) DO NOTHING;

