-- incoterm: Incoterms 2025 (15 rows).
INSERT INTO ferp_dictionary_entries
    (dictionary, code, label, sort, active, is_core, locale_overrides, extra)
SELECT * FROM (VALUES
    ('incoterm', 'EXW', 'Ex Works', 0, true, TRUE, '{}'::jsonb, '{"core":"true","description":"Ex Works, au départ non chargé, non dédouané sortie d''usine (uniquement adapté aux flux domestiques, nationaux)"}'::jsonb),
    ('incoterm', 'FCA', 'Free Carrier', 0, true, TRUE, '{}'::jsonb, '{"core":"true","description":"Free Carrier, marchandises dédouanées et chargées dans le pays de départ, chez le vendeur ou chez le commissionnaire de transport de l''acheteur"}'::jsonb),
    ('incoterm', 'FAS', 'Free Alongside Ship', 0, true, TRUE, '{}'::jsonb, '{"core":"true","description":"Free Alongside Ship, sur le quai du port de départ"}'::jsonb),
    ('incoterm', 'FOB', 'Free On Board', 0, true, TRUE, '{}'::jsonb, '{"core":"true","description":"Free On Board, chargé sur le bateau, les frais de chargement dans celui-ci étant fonction du liner term indiqué par la compagnie maritime (à la charge du vendeur)"}'::jsonb),
    ('incoterm', 'CFR', 'Cost and Freight', 0, true, TRUE, '{}'::jsonb, '{"core":"true","description":"Cost and Freight, chargé dans le bateau, livraison au port de départ, frais payés jusqu''au port d''arrivée, sans assurance pour le transport, non déchargé du navire à destination (les frais de déchargement sont inclus ou non au port d''arrivée)"}'::jsonb),
    ('incoterm', 'CIF', 'Cost, Insurance, Freight', 0, true, TRUE, '{}'::jsonb, '{"core":"true","description":"Cost, Insurance and Freight, chargé sur le bateau, frais jusqu''au port d''arrivée, avec l''assurance marchandise transportée souscrite par le vendeur pour le compte de l''acheteur (couverture standard, 10% de la valeur commerciale)"}'::jsonb),
    ('incoterm', 'CPT', 'Carriage Paid To', 0, true, TRUE, '{}'::jsonb, '{"core":"true","description":"Carriage Paid To, livraison au premier transporteur, frais jusqu''au déchargement du mode de transport, sans assurance pour le transport"}'::jsonb),
    ('incoterm', 'CIP', 'Carriage Insurance Paid', 0, true, TRUE, '{}'::jsonb, '{"core":"true","description":"Carriage and Insurance Paid to, idem CPT, avec assurance marchandise transportée souscrite par le vendeur pour le compte de l''acheteur (couverture tous risques)"}'::jsonb),
    ('incoterm', 'DAT', 'Delivered At Terminal', 0, false, TRUE, '{}'::jsonb, '{"core":"true","description":"Delivered At Terminal, marchandises (déchargées) livrées sur quai, dans un terminal maritime, fluvial, aérien, routier ou ferroviaire désigné (dédouanement import, et post-acheminement payés par l''acheteur)"}'::jsonb),
    ('incoterm', 'DAP', 'Delivered At Place', 0, true, TRUE, '{}'::jsonb, '{"core":"true","description":"Delivered At Place, marchandises (non déchargées) mises à disposition de l''acheteur dans le pays d''importation au lieu précisé dans le contrat (déchargement, dédouanement import payé par l''acheteur)"}'::jsonb),
    ('incoterm', 'DDP', 'Delivered Duty Paid', 0, true, TRUE, '{}'::jsonb, '{"core":"true","description":"Delivered Duty Paid, marchandises (non déchargées) livrées à destination finale, dédouanement import et taxes à la charge du vendeur ; l''acheteur prend en charge uniquement le déchargement (si exclusion des taxes type TVA, le préciser clairement)"}'::jsonb),
    ('incoterm', 'DPU', 'Delivered at Place Unloaded', 0, true, TRUE, '{}'::jsonb, '{"core":"true","description":"Delivered at Place Unloaded, marchandises déchargées et livrées au lieu de destination désigné (remplace DAT, élargit les lieux de livraison possibles)"}'::jsonb),
    ('incoterm', 'DTP', 'Delivered at Terminal Paid', 0, false, TRUE, '{}'::jsonb, '{"core":"true","description":"Delivered at Terminal Paid, marchandises livrées et dédouanées dans un terminal du pays de destination (proposition non officielle, parfois utilisée en contrat)"}'::jsonb),
    ('incoterm', 'DPP', 'Delivered at Place Paid', 0, false, TRUE, '{}'::jsonb, '{"core":"true","description":"Delivered at Place Paid, marchandises livrées et dédouanées à une adresse précise du pays de destination (proposition non officielle)"}'::jsonb),
    ('incoterm', 'DTP(DHL)', 'Duties and Taxes Paid', 0, false, TRUE, '{}'::jsonb, '{"core":"true","description":"Duties and Taxes Paid (service DHL) : l''expéditeur paie les droits de douane et taxes à l''importation, évitant tout frais supplémentaire pour le destinataire (spécifique à DHL)"}'::jsonb)
) AS v (dictionary, code, label, sort, active, is_core, locale_overrides, extra)
ON CONFLICT (dictionary, code) DO NOTHING;

